import { ark } from "@ark-ui/solid/factory";
import { announcementRecipe } from "@pisagor/recipes/announcement";
import { cn } from "@pisagor/utils";
import type { ComponentProps, JSX } from "solid-js";
import { Show, splitProps } from "solid-js";
import { AnnouncementContext, useAnnouncement } from "./announcement.context";

type AnnouncementTitleProps = ComponentProps<typeof ark.span>;

type AnnouncementRootProps = Omit<ComponentProps<typeof ark.div>, "title"> & {
  role?: "status" | "alert";
  recipe?: typeof announcementRecipe;
};

export interface AnnouncementProps
  extends Omit<AnnouncementRootProps, "children"> {
  badge?: JSX.Element;
  title?: JSX.Element;
  titleProps?: Omit<AnnouncementTitleProps, "children" | "class">;
}

export function AnnouncementRoot(props: AnnouncementRootProps): JSX.Element {
  const [local, rest] = splitProps(props, [
    "role",
    "children",
    "recipe",
    "class",
  ]);
  const slots = () => (local.recipe ?? announcementRecipe)();

  return (
    <AnnouncementContext value={{ slots: slots() }}>
      <ark.div
        {...rest}
        class={slots().base({ class: cn(local.class) })}
        data-part="root"
        data-scope="announcement"
        role={local.role ?? "status"}
      >
        {local.children}
      </ark.div>
    </AnnouncementContext>
  );
}

export function AnnouncementTitle(props: AnnouncementTitleProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const { slots } = useAnnouncement();

  return (
    <ark.span
      {...rest}
      class={slots.title({ class: cn(local.class) })}
      data-part="title"
      data-scope="announcement"
    />
  );
}

export function AnnouncementShorthand(props: AnnouncementProps): JSX.Element {
  const [local, rest] = splitProps(props, ["badge", "title", "titleProps"]);

  return (
    <AnnouncementRoot {...rest}>
      {local.badge}
      <Show when={local.title !== undefined}>
        <AnnouncementTitle {...local.titleProps}>
          {local.title}
        </AnnouncementTitle>
      </Show>
    </AnnouncementRoot>
  );
}

import type { AnnouncementRecipe } from "@pisagor/recipes/announcement";
import { createContext } from "../../utils";

interface AnnouncementContextValue {
  slots: AnnouncementRecipe;
}

export const { AnnouncementContext, useAnnouncement } =
  createContext<AnnouncementContextValue>()({
    name: "Announcement",
  });

import {
  AnnouncementRoot,
  AnnouncementShorthand,
  AnnouncementTitle,
} from "./announcement";

export type { AnnouncementProps } from "./announcement";

export const Announcement = Object.assign(AnnouncementShorthand, {
  Root: AnnouncementRoot,
  Title: AnnouncementTitle,
});

import { appShellRecipe } from "@pisagor/recipes/app-shell";
import type { ComponentProps, JSX } from "solid-js";
import { createEffect, createSignal, onCleanup, splitProps } from "solid-js";
import {
  APP_SHELL_DEFAULT_INSPECTOR_RESIZABLE_PROPS,
  APP_SHELL_DEFAULT_PANEL_RESIZABLE_PROPS,
  AppShellContext,
  type AppShellFixedStackVar,
  type AppShellPlacement,
  type AppShellRailState,
  type AppShellRegionVar,
  type AppShellSideState,
  ZERO_FIXED_STACK_VARS,
  ZERO_REGION_VARS,
} from "./app-shell.context";

const APP_SHELL_GRID_COLUMNS = `
  var(--app-shell-start-inspector-width, 0px)
  var(--app-shell-start-rail-width, 0px)
  var(--app-shell-start-panel-width, 0px)
  minmax(0, 1fr)
  var(--app-shell-end-panel-width, 0px)
  var(--app-shell-end-rail-width, 0px)
  var(--app-shell-end-inspector-width, 0px)
`;

const APP_SHELL_CONTENT_ROW =
  '"start-inspector start-rail start-panel main end-panel end-rail end-inspector"';

const APP_SHELL_NAV_ROW =
  '"start-inspector navigation navigation navigation navigation navigation end-inspector"';

const APP_SHELL_BANNER_ROW =
  '"banner banner banner banner banner banner banner"';

export interface AppShellRootProps extends ComponentProps<"div"> {
  recipe?: typeof appShellRecipe;
}

export function AppShellRoot(props: AppShellRootProps): JSX.Element {
  const [local, rest] = splitProps(props, [
    "children",
    "recipe",
    "class",
    "style",
  ]);
  const slots = () => (local.recipe ?? appShellRecipe)();
  const [regionRevision, setRegionRevision] = createSignal(0);
  const [regionVars, setRegionVars] = createSignal({ ...ZERO_REGION_VARS });
  const [fixedStackVars, setFixedStackVars] = createSignal({
    ...ZERO_FIXED_STACK_VARS,
  });
  const panelStates = {
    current: {} as Partial<Record<AppShellPlacement, AppShellSideState>>,
  };
  const inspectorStates = {
    current: {} as Partial<Record<AppShellPlacement, AppShellSideState>>,
  };
  const railStates = {
    current: {} as Partial<Record<AppShellPlacement, AppShellRailState>>,
  };
  const shellRef = { current: null as HTMLDivElement | null };
  const [regionResizing, setRegionResizing] = createSignal(false);

  const setRegionVar = (name: AppShellRegionVar, value: string) => {
    setRegionVars((current) => {
      if (current[name] === value) return current;
      return { ...current, [name]: value };
    });
  };

  const setFixedStackVar = (name: AppShellFixedStackVar, value: string) => {
    setFixedStackVars((current) => {
      if (current[name] === value) return current;
      return { ...current, [name]: value };
    });
  };

  createEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.code === "Backslash") {
        event.preventDefault();
        panelStates.current.start?.toggle();
      }
    };
    window.addEventListener("keydown", onKeyDown);
    onCleanup(() => window.removeEventListener("keydown", onKeyDown));
  });

  const notifyRegionChange = () => setRegionRevision((r) => r + 1);

  const gridStyle = {
    "grid-template-areas": [
      APP_SHELL_BANNER_ROW,
      APP_SHELL_NAV_ROW,
      APP_SHELL_CONTENT_ROW,
    ].join(" "),
    "grid-template-columns": APP_SHELL_GRID_COLUMNS,
    "grid-template-rows": "auto auto auto",
  };

  return (
    <AppShellContext
      value={{
        defaultInspectorResizableProps:
          APP_SHELL_DEFAULT_INSPECTOR_RESIZABLE_PROPS,
        defaultPanelResizableProps: APP_SHELL_DEFAULT_PANEL_RESIZABLE_PROPS,
        fixedStackVars,
        inspectorStates,
        notifyRegionChange,
        panelStates,
        railStates,
        regionResizing,
        regionRevision,
        regionVars,
        setFixedStackVar,
        setRegionResizing,
        setRegionVar,
        shellRef,
        slots: slots(),
      }}
    >
      <div
        {...rest}
        class={slots().base({ class: local.class })}
        data-part="root"
        data-resizing={regionResizing() ? "" : undefined}
        data-scope="app-shell"
        ref={(el) => {
          shellRef.current = el;
        }}
        style={{
          ...regionVars(),
          ...fixedStackVars(),
          ...gridStyle,
          ...(typeof local.style === "object" &&
          local.style &&
          !Array.isArray(local.style)
            ? (local.style as Record<string, string>)
            : {}),
        }}
      >
        {local.children}
      </div>
    </AppShellContext>
  );
}

import type { AppShellRecipe } from "@pisagor/recipes/app-shell";
import type { Accessor } from "solid-js";
import { createMemo, createSignal } from "solid-js";
import { createContext } from "../../utils";

export type AppShellPlacement = "start" | "end";
export type AppShellRegionPosition = "fixed" | "relative";
export type AppShellResizeHandlePosition = "bottom" | "center" | "top";

export interface AppShellResizableProps {
  enabled?: boolean;
  handlePosition?: AppShellResizeHandlePosition;
}

export const APP_SHELL_DEFAULT_PANEL_RESIZABLE_PROPS = {
  enabled: true,
  handlePosition: "top",
} as const satisfies Required<
  Pick<AppShellResizableProps, "enabled" | "handlePosition">
>;

export const APP_SHELL_DEFAULT_INSPECTOR_RESIZABLE_PROPS = {
  enabled: true,
  handlePosition: "top",
} as const satisfies Required<
  Pick<AppShellResizableProps, "enabled" | "handlePosition">
>;

export type AppShellFixedStackVar =
  | "--app-shell-banner-height"
  | "--app-shell-navigation-height";

export type AppShellRegionVar =
  | "--app-shell-end-inspector-width"
  | "--app-shell-end-panel-width"
  | "--app-shell-end-rail-width"
  | "--app-shell-start-inspector-width"
  | "--app-shell-start-panel-width"
  | "--app-shell-start-rail-width";

export interface AppShellSideState {
  open: Accessor<boolean>;
  setOpen: (open: boolean | ((current: boolean) => boolean)) => void;
  toggle: () => void;
}

export interface AppShellRailState {
  activeRailId: Accessor<string | undefined>;
  placement: AppShellPlacement;
  setActiveRailId: (id: string) => void;
}

export type MutableRef<T> = { current: T };

interface AppShellContextValue {
  inspectorStates: MutableRef<
    Partial<Record<AppShellPlacement, AppShellSideState>>
  >;
  notifyRegionChange: () => void;
  panelStates: MutableRef<
    Partial<Record<AppShellPlacement, AppShellSideState>>
  >;
  railStates: MutableRef<Partial<Record<AppShellPlacement, AppShellRailState>>>;
  regionResizing: Accessor<boolean>;
  regionRevision: Accessor<number>;
  regionVars: Accessor<Record<AppShellRegionVar, string>>;
  fixedStackVars: Accessor<Record<AppShellFixedStackVar, string>>;
  defaultInspectorResizableProps: typeof APP_SHELL_DEFAULT_INSPECTOR_RESIZABLE_PROPS;
  defaultPanelResizableProps: typeof APP_SHELL_DEFAULT_PANEL_RESIZABLE_PROPS;
  setRegionResizing: (resizing: boolean) => void;
  setFixedStackVar: (name: AppShellFixedStackVar, value: string) => void;
  setRegionVar: (name: AppShellRegionVar, value: string) => void;
  shellRef: MutableRef<HTMLDivElement | null>;
  slots: AppShellRecipe;
}

interface UseSideStateOptions {
  getControlledOpen?: () => boolean | undefined;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
}

export const ZERO_FIXED_STACK_VARS: Record<AppShellFixedStackVar, string> = {
  "--app-shell-banner-height": "0px",
  "--app-shell-navigation-height": "0px",
};

export const ZERO_REGION_VARS: Record<AppShellRegionVar, string> = {
  "--app-shell-end-inspector-width": "0px",
  "--app-shell-end-panel-width": "0px",
  "--app-shell-end-rail-width": "0px",
  "--app-shell-start-inspector-width": "0px",
  "--app-shell-start-panel-width": "0px",
  "--app-shell-start-rail-width": "0px",
};

export const { AppShellContext, useAppShell } =
  createContext<AppShellContextValue>()({
    name: "AppShell",
  });

export function useSideState({
  defaultOpen = false,
  getControlledOpen,
  onOpenChange,
}: UseSideStateOptions): AppShellSideState {
  const [uncontrolled, setUncontrolled] = createSignal(defaultOpen);
  const open = createMemo(() => {
    const controlled = getControlledOpen?.();
    return controlled !== undefined ? !!controlled : uncontrolled();
  });

  const setOpenValue = (next: boolean) => {
    if (getControlledOpen?.() === undefined) setUncontrolled(next);
    onOpenChange?.(next);
  };

  const setOpen = (value: boolean | ((current: boolean) => boolean)) => {
    setOpenValue(typeof value === "function" ? value(open()) : value);
  };

  const toggle = () => setOpenValue(!open());

  return { open, setOpen, toggle };
}

import { AppShellRoot } from "./app-shell";
import { AppShellBanner } from "./banner";
import {
  AppShellInspector,
  AppShellInspectorContent,
