const SIDEBAR_STORAGE_KEY = "sidebar_state";
const SIDEBAR_WIDTH = "16rem";
const SIDEBAR_WIDTH_MOBILE = "18rem";
const SIDEBAR_WIDTH_ICON = "3rem";

export function SidebarProvider(props: SidebarProviderProps): JSX.Element {
  const [local, rest] = splitProps(props, [
    "defaultOpen",
    "open",
    "onOpenChange",
    "recipe",
    "class",
    "style",
    "children",
  ]);

  const isMobile = useIsMobile();
  const [openMobile, setOpenMobile] = createSignal(false);
  const [uncontrolledOpen, setUncontrolledOpen] = createSignal(
    local.defaultOpen ?? true,
  );

  const open = createMemo(() =>
    local.open !== undefined ? !!local.open : uncontrolledOpen(),
  );

  const setOpen = (value: boolean) => {
    if (local.open === undefined) {
      setUncontrolledOpen(value);
    }
    local.onOpenChange?.(value);
    if (typeof localStorage !== "undefined") {
      localStorage.setItem(SIDEBAR_STORAGE_KEY, String(value));
    }
  };

  const toggleSidebar = () => {
    if (isMobile()) {
      setOpenMobile((v) => !v);
    } else {
      setOpen(!open());
    }
  };

  createEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "b") {
        event.preventDefault();
        toggleSidebar();
      }
    };
    window.addEventListener("keydown", onKeyDown);
    onCleanup(() => window.removeEventListener("keydown", onKeyDown));
  });

  const state = createMemo<"expanded" | "collapsed">(() =>
    open() ? "expanded" : "collapsed",
  );
  const slots = () => (local.recipe ?? sidebarRecipe)();

  const contextValue: SidebarContextProps = {
    isMobile,
    open,
    openMobile,
    setOpen,
    setOpenMobile,
    slots: slots(),
    state,
    toggleSidebar,
  };

  const style = () => {
    const base: Record<string, string> = {
      "--sidebar-width": SIDEBAR_WIDTH,
      "--sidebar-width-icon": SIDEBAR_WIDTH_ICON,
    };
    const s = local.style;
    if (s && typeof s === "object" && !Array.isArray(s)) {
      return { ...base, ...(s as Record<string, string>) };
    }
    return base;
  };

  return (
    <SidebarContext value={contextValue}>
      <ark.div
        {...rest}
        class={slots().wrapper({ class: cn(local.class) })}
        data-part="wrapper"
        data-scope="sidebar"
        style={style()}
      >
        {local.children}
      </ark.div>
    </SidebarContext>
  );
}

export function SidebarRoot(props: SidebarProps): JSX.Element {
  const [local, rest] = splitProps(props, [
    "collapsible",
    "placement",
    "variant",
    "class",
    "children",
  ]);
  const { isMobile, openMobile, setOpenMobile, slots, state } = useSidebar();
  const collapsible = () => local.collapsible ?? "offcanvas";
  const placement = () => local.placement ?? "left";
  const variant = () => local.variant ?? "sidebar";
  const padded = () => variant() === "floating" || variant() === "inset";

  return (
    <Show
      fallback={
        <Show
          fallback={
            <ark.div
              {...rest}
              class={slots.peer({ class: cn(local.class) })}
              data-collapsible={state() === "collapsed" ? collapsible() : ""}
              data-part="root"
              data-placement={placement()}
              data-scope="sidebar"
              data-state={state()}
              data-variant={variant()}
            >
              <ark.div
                class={slots.gap({ padded: padded(), placement: placement() })}
                data-part="gap"
                data-scope="sidebar"
              />
              <ark.div
                class={slots.container({
                  class: cn(local.class),
                  padded: padded(),
                  placement: placement(),
                })}
                data-part="container"
                data-scope="sidebar"
              >
                <ark.div
                  class={slots.inner()}
                  data-part="inner"
                  data-scope="sidebar"
                  data-sidebar="sidebar"
                >
                  {local.children}
                </ark.div>
              </ark.div>
            </ark.div>
          }
          when={isMobile()}
        >
          <Sheet
            onOpenChange={(details) => setOpenMobile(details.open)}
            open={openMobile()}
          >
            <Sheet.Content
              {...rest}
              class={slots.mobile()}
              data-mobile="true"
              data-sidebar="sidebar"
              placement={placement() === "left" ? "left" : "right"}
              style={{ "--sidebar-width": SIDEBAR_WIDTH_MOBILE }}
            >
              <Sheet.Header class={slots.mobileHeader()}>
                <Sheet.Title>Sidebar</Sheet.Title>
                <Sheet.Description>
                  Displays the mobile sidebar.
                </Sheet.Description>
              </Sheet.Header>
              <ark.div class={slots.mobileBody()}>{local.children}</ark.div>
            </Sheet.Content>
          </Sheet>
        </Show>
      }
      when={collapsible() === "none"}
    >
      <ark.div
        {...rest}
        class={slots.base({ class: cn(local.class) })}
        data-part="root"
        data-scope="sidebar"
      >
        {local.children}
      </ark.div>
    </Show>
  );
}

export function SidebarTrigger(props: ButtonProps): JSX.Element {
  const [local, rest] = splitProps(props, ["onClick", "class"]);
  const { slots, toggleSidebar } = useSidebar();

