  return (
    <ark.div
      {...rest}
      class={slots().content({ class: cn(local.class) })}
      data-part="content"
      data-scope="skip-nav"
      id={local.id ?? SKIP_NAV_ID}
      tabIndex={-1}
    />
  );
}

