}

export function TableHeader(props: TableHeaderProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const { slots } = useTable();
  return (
    <ark.thead
      {...rest}
      class={slots.header({ class: cn(local.class) })}
      data-part="header"
      data-scope="table"
    />
  );
}

export function TableBody(props: TableBodyProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const { slots } = useTable();
  return (
    <ark.tbody
      {...rest}
      class={slots.body({ class: cn(local.class) })}
      data-part="body"
      data-scope="table"
    />
  );
}

export function TableFooter(props: TableFooterProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const { slots } = useTable();
  return (
    <ark.tfoot
      {...rest}
      class={slots.footer({ class: cn(local.class) })}
      data-part="footer"
      data-scope="table"
    />
  );
}

export function TableRow(props: TableRowProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const { slots } = useTable();
  return (
    <ark.tr
      {...rest}
      class={slots.row({ class: cn(local.class) })}
      data-part="row"
      data-scope="table"
    />
  );
}

export function TableHead(props: TableHeadProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const { slots } = useTable();
  return (
    <ark.th
      {...rest}
      class={slots.head({ class: cn(local.class) })}
      data-part="head"
      data-scope="table"
    />
  );
}

export function TableCell(props: TableCellProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const { slots } = useTable();
  return (
    <ark.td
      {...rest}
      class={slots.cell({ class: cn(local.class) })}
      data-part="cell"
      data-scope="table"
    />
  );
}

export function TableCaption(props: TableCaptionProps): JSX.Element {
  const [local, rest] = splitProps(props, ["class"]);
  const { slots } = useTable();
  return (
    <ark.caption
      {...rest}
      class={slots.caption({ class: cn(local.class) })}
      data-part="caption"
      data-scope="table"
    />
  );
}

import type { TableRecipe } from "@pisagor/recipes/table";
import { createContext } from "../../utils";

interface TableContextValue {
  slots: TableRecipe;
}

export const { TableContext, useTable } = createContext<TableContextValue>()({
  name: "Table",
});

import {
  TableBody,
  TableCaption,
  TableCell,
  TableFooter,
  TableHead,
  TableHeader,
  TableRoot,
  TableRow,
} from "./table";

export type {
  TableBodyProps,
  TableCaptionProps,
  TableCellProps,
  TableFooterProps,
  TableHeaderProps,
  TableHeadProps,
  TableProps,
  TableRowProps,
